use vstd::prelude::*;

verus! {

    /// Given a non‐empty vector of characters `arr`, produce a new vector `outarr`
    /// whose elements are the characters of `arr` in reverse order.
    ///
    /// Post‐condition: for all 0 ≤ k < arr.len(),
    ///     outarr[k] == arr[arr.len() - 1 - k]
    fn yarra(arr: &Vec<char>) -> (outarr: Vec<char>)
        requires
            // as per the problem statement, the input is non‐empty
            arr.len() > 0,
        ensures
            // the output has the same length as the input
            outarr.len() == arr.len(),
            // and it is the exact reversal
            forall|k: usize| k < arr.len() ==> outarr.index(k) == arr.index(arr.len() - 1 - k),
    {
        let n: usize = arr.len();
        // allocate with capacity n so pushes cannot overflow
        let mut out: Vec<char> = Vec::with_capacity(n);
        let mut i: usize = 0;

        // We build `out` one character at a time;
        // at iteration `i` we have already pushed `i` chars,
        // namely those for indices 0..i of the reversed vector.
        while i < n
            invariant
                // loop counter bounds
                i <= n,
                // we have pushed exactly `i` characters so far
                out.len() == i,
                // partial correctness: for every k < i, out[k] == arr[n-1-k]
                forall|k: usize| k < i ==> out.index(k) == arr.index(n - 1 - k),
                // the input length stays fixed
                arr.len() == n,
            decreases n - i,
        {
            // pick the next character from the “tail” of `arr`
            let c: char = arr.index(n - 1 - i);
            out.push(c);
            i += 1;
        }

        outarr = out;
    }

}

